import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type EnergyChartProps = Record<string, any>;

const Bar: React.FC<{
  value: number;
  label: string;
  delay: number;
  maxHeight: number;
  gradient: string;
}> = ({ value, label, delay, maxHeight, gradient }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  const height = interpolate(progress, [0, 1], [0, value]);
  const opacity = interpolate(progress, [0, 0.5], [0, 1]);
  const labelOpacity = interpolate(frame - delay - 10, [0, 10], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "flex-end",
        height: "100%",
        width: "24%", // Reduced width to allow for more spread
        gap: 10,
      }}
    >
      {/* Value Label (Top) */}
      <div
        style={{
          opacity: labelOpacity,
          fontFamily: "DM Sans",
          fontSize: 24,
          fontWeight: 500,
          color: "#333",
          transform: `translateY(${interpolate(progress, [0, 1], [20, 0])}px)`,
        }}
      >
        {Math.round(height)}
      </div>

      {/* Bar */}
      <div
        style={{
          width: "100%",
          height: `${(height / 100) * maxHeight}px`,
          background: gradient,
          borderRadius: 40,
          opacity,
          transformOrigin: "bottom center",
          transform: `scaleY(${progress})`,
        }}
      />

      {/* X-Axis Label (Bottom) */}
      <div
        style={{
          opacity: labelOpacity,
          fontFamily: "DM Sans",
          fontSize: 24,
          fontWeight: 500,
          color: "#000",
        }}
      >
        {label}
      </div>
    </div>
  );
};

const EnergyChart: React.FC<EnergyChartProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 6,
  titleText = "Boost Energy Levels",
  mainPercentage = 45,
  mainNumberLetterSpacing = 20,
  bar1Value = 20,
  bar2Value = 30,
  bar3Value = 45,
  bar1Label = "Low",
  bar2Label = "Normal",
  bar3Label = "High",
  gradientStart = "#9f8dfa", // Purple-ish
  gradientEnd = "#fcaeb0", // Peach-ish
  cardColor = "#ffffff",
}) => {
  useFontLoader(["DM Sans"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Calculate responsive square dimensions for 1:1 centering
  const minDim = Math.min(width, height);
  const cardSize = minDim * 0.85;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Card Animation
  const cardSpring = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 90 },
  });

  const cardScale = interpolate(cardSpring, [0, 1], [0.8, 1]);
  const cardOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // Main Number Counter
  const countProgress = spring({
    frame: frame - 15,
    fps,
    config: { damping: 100, stiffness: 50, mass: 2 },
  });
  
  const currentCount = Math.round(interpolate(countProgress, [0, 1], [0, mainPercentage]));
  
  // Staggered bars
  const bars = [
    { val: bar1Value, label: bar1Label, delay: 20 },
    { val: bar2Value, label: bar2Label, delay: 30 },
    { val: bar3Value, label: bar3Label, delay: 40 },
  ];

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "DM Sans",
      }}
    >
      <div
        style={{
          width: cardSize,
          height: cardSize,
          backgroundColor: cardColor,
          borderRadius: 60,
          boxShadow: "0px 20px 60px rgba(0,0,0,0.1)",
          padding: cardSize * 0.08, // Responsive padding
          display: "flex",
          flexDirection: "column",
          transform: `scale(${cardScale})`,
          opacity: cardOpacity,
        }}
      >
        {/* Header */}
        <div
          style={{
            fontSize: 48,
            fontWeight: 700,
            color: "#1a1a1a",
            marginBottom: 20, // Reduced margin to align closer to the number
            opacity: interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" }),
            transform: `translateY(${interpolate(frame, [10, 30], [20, 0], { extrapolateRight: "clamp" })}px)`,
          }}
        >
          {titleText}
        </div>

        {/* Content Body - Changed to Column to stack items vertically */}
        <div style={{ display: "flex", flex: 1, flexDirection: "column", gap: 10 }}>
          
          {/* Top Section: Big Percentage */}
          <div
            style={{
              display: "flex",
              alignItems: "flex-start",
              justifyContent: "flex-start",
              marginBottom: 20,
            }}
          >
            <div style={{ display: "flex", alignItems: "flex-start" }}>
              <span
                style={{
                  fontSize: cardSize * 0.22, // Responsive font size
                  fontWeight: 500, 
                  lineHeight: 0.8,
                  color: "#000",
                  letterSpacing: mainNumberLetterSpacing, // User-adjustable spacing
                }}
              >
                {currentCount}
              </span>
              <span
                style={{
                  fontSize: cardSize * 0.08, // Responsive font size
                  fontWeight: 500,
                  marginTop: 20,
                  marginLeft: cardSize * 0.05, // Increased spacing for visual breathing room
                  color: "#000",
                }}
              >
                %
              </span>
            </div>
          </div>

          {/* Bottom Section: Bars */}
          <div
            style={{
              flex: 1,
              display: "flex",
              flexDirection: "row",
              alignItems: "flex-end", // Align bars to bottom
              justifyContent: "space-between", // Spread bars out
              paddingBottom: 20, // Space for labels
              height: "100%",
              width: "100%",
            }}
          >
            {bars.map((bar, i) => (
              <Bar
                key={i}
                value={bar.val}
                label={bar.label}
                delay={bar.delay}
                maxHeight={cardSize * 0.4} // Max height relative to card size
                gradient={`linear-gradient(180deg, ${gradientStart} 0%, ${gradientEnd} 100%)`}
              />
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default EnergyChart;